/**
 * Demo story data for scripts/seed-demo.ts. Pure data, no I/O.
 *
 * The first 12 Sales candidates are ported word for word from the hackathon demo (/demo/index.html):
 * same names, resume scores, quality scores, reasons, quotes, must-have results, flags and summaries.
 * The rest are new, written in the same voice. Every quote below is spoken by the candidate in the
 * transcript the seed script builds, so the app's quote verification passes.
 *
 * Phones are generated by the seed script as +1555… numbers, which the dispatcher never dials.
 */

export type JobKey = "sales" | "sde";
export type QualityKey = "skills" | "experience" | "confidence" | "culture_fit" | "curiosity" | "learning_drive" | "storytelling";
export const QUALITY_ORDER: QualityKey[] = ["skills", "experience", "confidence", "culture_fit", "curiosity", "learning_drive", "storytelling"];

/** [score 1-5 | null, reason, ...quotes] */
export type Q = [number | null, string, ...string[]];
export const NE = "Not enough evidence on the call to score this.";
export const q = (s: number | null, r?: string, ...quotes: string[]): Q => [s, r ?? NE, ...quotes];

export type DemoProfile = {
  current_role: string | null;
  years_experience: number | null;
  location: string | null;
  skills: string[];
  companies: string[];
  education: string | null;
  notice_period_days: number | null;
  languages: string[];
};

export type DemoCall = {
  outcome: "completed" | "short_exit" | "no_answer" | "rescheduled" | "declined";
  /** Seconds. Omitted for the 12 ported stories: computed exactly like the demo did. */
  duration_s?: number;
  /** Days before today (IST) and the IST clock time the call started. */
  daysAgo: number;
  at: string;
  termination: string;
  /** Callback booked for tomorrow at this IST time ("17:00"). */
  callbackTomorrowAt?: string;
};

export type DemoCandidate = {
  key: string;
  job: JobKey;
  name: string;
  /** csv | form | portal_mock | naukri | linkedin. Omitted for the 12 ported stories (demo's hash rule). */
  source?: string;
  resume: number;
  resume_note: string;
  profile: DemoProfile;
  /** Seven entries in QUALITY_ORDER. Omitted when the call produced nothing to score. */
  qualities?: Q[];
  /** One per job must-have: [met, the candidate's own words]. */
  mustHaves?: [boolean, string][];
  flags?: {
    other?: { job: JobKey | null; title: string; reason: string };
    culture?: boolean;
    intern?: boolean;
    mismatch?: { claim_quote: string; resume_line: string }[];
  };
  summary?: string;
  shortExit?: boolean;
  call: DemoCall;
  /** Candidate status after the call. Default: 'scored' when scored. */
  status?: "imported" | "queued" | "scored";
  /** Hand-written transcript (used instead of the generated one). */
  transcript?: string;
  /** Extra exchange inserted before the close: [aditi, candidate]. */
  extra?: [string, string][];
};

const langs = ["English", "Hindi"];
const p = (
  current_role: string | null,
  years_experience: number | null,
  location: string,
  skills: string[],
  companies: string[],
  education: string,
  notice_period_days: number | null = 30,
  languages: string[] = langs,
): DemoProfile => ({ current_role, years_experience, location, skills, companies, education, notice_period_days, languages });

